export type Ingredient = {
  item: string;
  amount: string;
  category: "produce" | "protein" | "pantry" | "fridge" | "frozen";
};

export type MealType = "Lunch" | "Dinner";
export type RecipeCategory = "Dinner" | "Lunch";

export type MealPlanEntry = {
  id: string;
  day: string;
  mealType: MealType;
  title: string;
  description: string;
  serves: number;
  prepTime: string;
  sourceName: string;
  sourceUrl: string;
  main: string;
  side?: string;
  highlights: string[];
  ingredients: Ingredient[];
};

export type RecipeLibraryEntry = {
  id: string;
  title: string;
  category: RecipeCategory;
  sourceName: string;
  sourceUrl: string;
  imageUrl: string;
  description: string;
  favourite: boolean;
  tags: string[];
  plannedDays: string[];
  prepTime?: string;
  serves?: number;
  ingredients?: Ingredient[];
  instructions?: string[];
};

export type RecipeDetailsEntry = Pick<RecipeLibraryEntry, "prepTime" | "serves" | "ingredients" | "instructions">;

